fn root(n: Text) -> Text uses ffi or fail {
    let args = [n]
    return try py("math", "sqrt", args)
}

fn main() uses io, ffi {
    check root("16") {
        ok v {
            print(v)
        }
        fail why {
            print(why)
        }
    }
}

